fn maximum(items: &[i32]) -> Option<i32> {
    let mut best = *items.first()?;
    for &value in items { if value > best { best = value; } }
    Some(best)
}
fn main() {
    println!("{:?}", maximum(&[4, 12, 3]));
    println!("{:?}", maximum(&[]));
}

fn identity<T>(value: T) -> T { value }
fn main() {
    let count = identity(14);
    let name = String::from("map");
    let returned = identity(name);
    println!("{} {}", count, returned);
}

struct Pair<T, U> { first: T, second: U }
fn main() {
    let entry = Pair { first: 7, second: "north" };
    println!("{} {}", entry.first, entry.second);
}

enum Slot<T> { Filled(T), Empty }
fn main() {
    let slot: Slot<i32> = Slot::Empty;
    match slot {
        Slot::Filled(value) => println!("{}", value),
        Slot::Empty => println!("empty"),
    }
    let _other = Slot::Filled(6);
}

struct Wrapper<T> { value: T }
impl<T> Wrapper<T> {
    fn get(&self) -> &T { &self.value }
}
fn main() {
    let item = Wrapper { value: String::from("guide") };
    println!("{}", item.get());
}

fn pass<T>(value: T) -> T { value }
fn main() {
    let amount = pass(19_i32);
    let enabled = pass(true);
    println!("{} {}", amount, enabled);
}

trait Label { fn label(&self) -> String; }
struct Gate { number: i32 }
impl Label for Gate {
    fn label(&self) -> String { format!("gate {}", self.number) }
}
fn main() {
    let gate = Gate { number: 4 };
    println!("{}", gate.label());
}

trait Score { fn score(&self) -> i32; }
struct Reading { correct: i32 }
impl Score for Reading {
    fn score(&self) -> i32 { self.correct * 5 }
}
fn main() {
    let reading = Reading { correct: 6 };
    println!("{}", reading.score());
}

trait Named {
    fn name(&self) -> &str;
    fn caption(&self) -> String { format!("item: {}", self.name()) }
}
struct Desk;
impl Named for Desk { fn name(&self) -> &str { "desk" } }
fn main() { println!("{}", Desk.caption()); }

use std::fmt::Display;
fn show(value: &impl Display) { println!("value={}", value); }
fn main() {
    show(&32);
    show(&"lake");
}

use std::fmt::Display;
fn answer() -> impl Display { 42_i32 }
fn main() { println!("{}", answer()); }

fn largest<T: PartialOrd>(items: &[T]) -> Option<&T> {
    let mut best = items.first()?;
    for item in items { if item > best { best = item; } }
    Some(best)
}
fn main() { println!("{:?}", largest(&[3, 18, 7])); }

use std::fmt::Display;
struct Pair<T> { a: T, b: T }
impl<T> Pair<T> { fn new(a: T, b: T) -> Self { Self { a, b } } }
impl<T: Display + PartialOrd> Pair<T> {
    fn show_larger(&self) {
        let value = if self.a >= self.b { &self.a } else { &self.b };
        println!("{}", value);
    }
}
fn main() { Pair::new(8, 13).show_larger(); }

fn main() {
    let owner = String::from("river");
    {
        let borrowed = &owner;
        println!("{}", borrowed);
    }
    println!("{}", owner);
}

fn main() {
    let count = 2;
    {
        let title = String::from("chapter");
        let reference = &title;
        println!("{} {}", count, reference);
    }
    println!("{}", count);
}

fn longer<'a>(a: &'a str, b: &'a str) -> &'a str {
    if a.len() >= b.len() { a } else { b }
}
fn main() {
    let left = String::from("forest");
    let right = String::from("bay");
    println!("{}", longer(&left, &right));
}

fn identity_ref<'a>(value: &'a i32) -> &'a i32 { value }
fn main() {
    let number = 21;
    let view = identity_ref(&number);
    println!("{}", view);
}

fn choose<'a>(a: &'a str, b: &'a str) -> &'a str {
    if a.len() > b.len() { a } else { b }
}
fn main() {
    let outer = String::from("mountain");
    {
        let inner = String::from("hill");
        println!("{}", choose(&outer, &inner));
    }
}

fn first<'a>(a: &'a str, _b: &str) -> &'a str { a }
fn main() {
    let owner = String::from("persistent");
    let result;
    {
        let temporary = String::from("short");
        result = first(&owner, &temporary);
    }
    println!("{}", result);
}

struct Note<'a> { text: &'a str }
fn main() {
    let source = String::from("borrowed note");
    let note = Note { text: &source };
    println!("{}", note.text);
}

fn echo(text: &str) -> &str { text }
fn main() {
    let message = String::from("echo");
    println!("{}", echo(&message));
}

struct Notice<'a> { text: &'a str }
impl<'a> Notice<'a> {
    fn announce(&self, prefix: &str) -> &str {
        println!("{}", prefix);
        self.text
    }
}
fn main() {
    let n = Notice { text: "arrival" };
    println!("{}", n.announce("notice"));
}

fn banner() -> &'static str { "learning desk" }
fn main() {
    let text: &'static str = banner();
    println!("{}", text);
}

use std::fmt::Display;
fn choose<'a, T>(a: &'a str, b: &'a str, note: T) -> &'a str
where T: Display {
    println!("{}", note);
    if a.len() >= b.len() { a } else { b }
}
fn main() { println!("{}", choose("road", "bay", 7)); }

fn same<T: PartialEq>(a: &T, b: &T) -> bool { a == b }
fn main() {
    println!("{}", same(&5, &5));
    println!("{}", same(&String::from("a"), &String::from("b")));
}
